import { Injectable } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { chatbotKnowledge, ChatbotTopic } from './chatbot-knowledge';
import { ChatbotHistoryMessageDto } from '../dtos/chatbot-message.dto';
import { chatbotSystemPrompt } from './chatbot-system-prompt';

/** Structured response generated by Gemini for a conversational turn. */
export interface ChatbotAiAnswer {
  reply: string;
  topic: ChatbotTopic | 'WELCOME' | 'UNKNOWN';
}

const ALLOWED_TOPICS: readonly string[] = [
  ...chatbotKnowledge.map((topic) => topic.id),
  'WELCOME',
  'UNKNOWN',
];

/**
 * Safely narrows an unknown value to a plain key-value record.
 * @param value Unknown parsed JSON value.
 * @returns Plain object record, or an empty object for non-object values.
 */
function record(value: unknown): Record<string, unknown> {
  return value !== null && typeof value === 'object' && !Array.isArray(value)
    ? (value as Record<string, unknown>)
    : {};
}

/** Integrates Google Gemini with strict JSON schema validation and fail-safe fallback. */
@Injectable()
export class ChatbotAiService {
  constructor(private readonly config: ConfigService) {}

  /**
   * Verifies that Gemini integration is enabled, keyed, and configured with a valid model ID.
   * @returns True when external Gemini calls may be dispatched.
   */
  isConfigured(): boolean {
    return (
      this.config.get<string>('CHATBOT_AI_ENABLED') === 'true' &&
      Boolean(this.config.get<string>('GEMINI_API_KEY')?.trim()) &&
      /^gemini-[a-z0-9.-]+$/.test(this.config.get<string>('CHATBOT_GEMINI_MODEL') ?? '')
    );
  }

  /**
   * Requests a structured conversational reply from Gemini.
   * @param message Current sanitized user message.
   * @param history Prior conversation turns with sensitive content redacted.
   * @param authenticated Whether the caller holds an authenticated session.
   * @returns Validated AI answer, or null on configuration absence, timeout, or schema failure.
   */
  async answer(
    message: string,
    history: ChatbotHistoryMessageDto[] = [],
    authenticated = true,
  ): Promise<ChatbotAiAnswer | null> {
    if (!this.isConfigured()) return null;
    try {
      const response = await this.requestGemini(message, history, authenticated);
      if (!response.ok) return null;
      return this.parseGeminiResponse(await response.json());
    } catch {
      return null;
    }
  }

  /**
   * Dispatches the HTTPS request to the Gemini `generateContent` endpoint.
   * @param message Current user message.
   * @param history Bounded conversation history.
   * @param authenticated Authentication flag for system instruction context.
   * @returns Raw fetch response.
   */
  private requestGemini(
    message: string,
    history: ChatbotHistoryMessageDto[],
    authenticated: boolean,
  ): Promise<Response> {
    const model = this.config.get<string>('CHATBOT_GEMINI_MODEL');
    return fetch(
      `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent`,
      {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'x-goog-api-key': this.config.get<string>('GEMINI_API_KEY') ?? '',
        },
        body: JSON.stringify({
          systemInstruction: { parts: [{ text: chatbotSystemPrompt(authenticated) }] },
          contents: [
            ...history.slice(-12).map((turn) => ({
              role: turn.role === 'assistant' ? 'model' : 'user',
              parts: [{ text: turn.content }],
            })),
            { role: 'user', parts: [{ text: message }] },
          ],
          generationConfig: {
            responseMimeType: 'application/json',
            responseSchema: {
              type: 'OBJECT',
              properties: {
                reply: { type: 'STRING' },
                topic: { type: 'STRING', enum: [...ALLOWED_TOPICS] },
              },
              required: ['reply', 'topic'],
            },
          },
        }),
        signal: AbortSignal.timeout(15000),
        redirect: 'error',
      },
    );
  }

  /**
   * Validates and extracts the structured reply and topic from a Gemini payload.
   * @param raw Parsed JSON response from Gemini.
   * @returns Validated answer, or null when finish reason, length, or schema fails.
   */
  private parseGeminiResponse(raw: unknown): ChatbotAiAnswer | null {
    const body = record(raw);
    const candidate = Array.isArray(body.candidates) ? record(body.candidates[0]) : {};
    if (candidate.finishReason !== 'STOP') return null;
    const parts = record(candidate.content).parts;
    if (!Array.isArray(parts)) return null;
    const text = parts
      .filter((part: unknown) => record(part).thought !== true)
      .map((part: unknown) => record(part).text)
      .filter((part) => typeof part === 'string')
      .join('');
    if (text.length > 16000) return null;
    const result = record(JSON.parse(text));
    const topic = ALLOWED_TOPICS.find((id) => id === result.topic);
    if (
      !topic ||
      typeof result.reply !== 'string' ||
      !result.reply.trim() ||
      result.reply.length > 2000
    ) {
      return null;
    }
    return { reply: result.reply.trim(), topic: topic as ChatbotAiAnswer['topic'] };
  }
}
